package com.foodflow.catalog.repository;
import com.foodflow.catalog.entity.MenuItem; import jakarta.persistence.LockModeType; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface MenuItemRepository extends JpaRepository<MenuItem,UUID>{Page<MenuItem> findByAvailableTrue(Pageable pageable); Page<MenuItem> findByRestaurantIdIsNotNullAndAvailableTrue(Pageable pageable); Page<MenuItem> findByRestaurantIdAndAvailableTrue(UUID restaurantId,Pageable pageable); Page<MenuItem> findByRestaurantId(UUID restaurantId,Pageable pageable); List<MenuItem> findByRestaurantId(UUID restaurantId); List<MenuItem> findByRestaurantIdIsNullAndRestaurantNameIgnoreCase(String restaurantName); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select m from MenuItem m where m.id=:id") Optional<MenuItem> findByIdForUpdate(@Param("id") UUID id);}
